// Golden values of the Sourcing domain logic (docs/spec/08 §1): the 3-way match, invoice decisions, KPI formulas,
// quote comparison, supplier scorecard aggregates and the My approvals items, computed from the prototype data set and
// checked against the prototype's own render values (src/features/procurement/procurement.golden.json, generated by
// scripts/proto-golden-procurement.ts).
import { describe, expect, it } from 'vitest';
import { moneyEur } from '@/lib/format';
import { makeT } from '@/i18n/translate';
import { awardRule, isoOfDisplayDate, rfqStatus, supplierInvoiceStatus, type SupplierGrade } from '@/server/db/codes';
import { PROTO } from '@/server/prototype';
import golden from '@/features/procurement/procurement.golden.json';
import {
  MATCH_DOT, blockingReason, canAwardRfq, compareQuotes, invoiceApprovalItems, invoiceChipStatuses, invoiceDecisions, invoiceKpis, match3, parseNewRfq,
  quotesText, receiptGap, rfqActions, rfqAwardItems, rfqHint, rfqKpis, sourcingHref, supplierAttention, supplierKpis,
} from './procurement';

/** R-013: the prototype's status date (Fri 25 Sep 2026), passed explicitly to the business-date rules. */
const STATUS_DATE_ISO = '2026-09-25';

interface ProtoInvoice { id: string; supplier: string; po: string; gr: string; amount: number; poAmt: number; grAmt: number; date: string; dueDate: string; status: string }
interface ProtoRfq { id: string; title: string; part: string; qty: number; due: string; status: string; rule: string; owner: string; quotes: [string, number, number, string, string, number][]; chosen: string | null }

const INVOICES = PROTO.INVOICES as ProtoInvoice[];
const RFQS = PROTO.RFQS as ProtoRfq[];
const SUPPLIERS = PROTO.SUPPLIERS as [string, number, number, number, SupplierGrade, number][];
const G = golden as unknown as {
  seed: Record<'en' | 'fr', { rfq: { kpis: { value: unknown; sub: string }[]; rows: Record<string, unknown>[] }; inv: { kpis: { value: unknown; sub: string }[]; rows: Record<string, unknown>[]; chips: [string, number][] }; sup: { kpis: { value: unknown; sub: string }[] } }>;
  rfqDrawers: Record<'en' | 'fr', Record<string, Record<string, { hint: string; quotes: Record<string, unknown>[] }>>>;
  invDrawers: Record<'en' | 'fr', Record<string, { rows: { state: string; dot: string }[]; meta: { k: string; v: string }[]; canApprove: boolean; canPartial: boolean; canReject: boolean }>>;
  scenarios: Record<'en' | 'fr', { afterPartial: { inv: { kpis: { value: unknown; sub: string }[] } }; afterReject: { inv: { kpis: { value: unknown; sub: string }[] } }; afterCompare: { rfq: { kpis: { value: unknown; sub: string }[] } } }>;
  myapprovals: Record<'en' | 'fr', Record<string, { kind: string; id: string; title: string; sub: string; when: string; who: string }[]>>;
};

const asMatch = (i: ProtoInvoice, amount = i.amount) => ({ hasPo: !!i.po, hasReceipt: !!i.gr, amountEur: amount, poAmountEur: i.poAmt, receiptAmountEur: i.grAmt });
const STATE_LABEL = { ok: 'Matched', partial: 'Partial receipt', diff: 'Amount differs', pending: 'Receipt pending', none: 'Missing' } as const;

describe('3-way match and invoice decisions (match3 4663, invRows 4665)', () => {
  it('match dots, gap, decision flags and drawer states equal the prototype for every seed invoice', () => {
    const rows = G.seed.en.inv.rows;
    for (const i of INVOICES) {
      const m = match3(asMatch(i));
      const status = supplierInvoiceStatus.code(i.status);
      const row = rows.find((r) => r.id === i.id)!;
      expect([i.id, [['PO', MATCH_DOT[m.po]], ['GR', MATCH_DOT[m.gr]], ['INV', MATCH_DOT.ok]]]).toEqual([i.id, row.m]);
      const gap = receiptGap(asMatch(i));
      expect([i.id, gap == null ? '—' : moneyEur(gap, 'en')]).toEqual([i.id, row.gapText]);
      const d = invoiceDecisions(status, m);
      expect([i.id, d.canApprove, d.canApprovePart]).toEqual([i.id, row.canApprove, row.canPartial]);
      const drawer = G.invDrawers.en[i.id];
      expect(d.canReject).toBe(drawer.canReject);
      expect(drawer.rows.slice(0, 2).map((r) => r.state)).toEqual([STATE_LABEL[m.po], STATE_LABEL[m.gr]]);
      expect(drawer.meta.find((x) => x.k === 'Blocking reason')!.v).toBe(blockingReason(status, m) ?? '—');
    }
  });

  it('seed states: HC-7781 and BX-55120 partial receipts, NV-1190 pending, CF-0921 and LE-2210 without receipt', () => {
    const m = Object.fromEntries(INVOICES.map((i) => [i.id, match3(asMatch(i))]));
    expect(m).toEqual({
      'INV-KS-4471': { po: 'ok', gr: 'ok' },
      'INV-HC-7781': { po: 'ok', gr: 'partial' },
      'INV-NV-1190': { po: 'ok', gr: 'pending' },
      'INV-BX-55120': { po: 'ok', gr: 'partial' },
      'INV-CF-0921': { po: 'ok', gr: 'none' },
      'INV-LE-2210': { po: 'none', gr: 'none' },
    });
    // Approving the received part: the amount becomes the receipt amount → receipt ok, order amount now differs.
    const hc = INVOICES.find((i) => i.id === 'INV-HC-7781')!;
    expect(match3(asMatch(hc, hc.grAmt))).toEqual({ po: 'diff', gr: 'ok' });
    expect(receiptGap(asMatch(hc, hc.grAmt))).toBeNull();
  });

  it('a rejected invoice can no longer be rejected (the prototype offered it again)', () => {
    expect(invoiceDecisions('rejected', { po: 'none', gr: 'none' }).canReject).toBe(false);
    expect(invoiceDecisions('approved_for_payment', { po: 'ok', gr: 'ok' })).toEqual({ canApprove: false, canApprovePart: false, canReject: false });
    expect(invoiceDecisions('awaiting_receipt', { po: 'ok', gr: 'ok' }).canApprove).toBe(true);
    expect(invoiceDecisions('blocked', { po: 'diff', gr: 'ok' }).canApprove).toBe(false);
  });

  it('an "Awaiting receipt" invoice whose receipt was accepted since (Deliveries QC) gives the match\'s blocking reason', () => {
    // Seed states keep the prototype texts.
    expect(blockingReason('awaiting_receipt', { po: 'ok', gr: 'pending' })).toBe('Goods not yet received');
    expect(blockingReason('awaiting_receipt', { po: 'ok', gr: 'none' })).toBe('Goods not yet received');
    // Received in full and matched: nothing blocks "Approve payment".
    expect(blockingReason('awaiting_receipt', { po: 'ok', gr: 'ok' })).toBeNull();
    expect(invoiceDecisions('awaiting_receipt', { po: 'ok', gr: 'ok' }).canApprove).toBe(true);
    expect(blockingReason('awaiting_receipt', { po: 'diff', gr: 'ok' })).toBe('Amount differs from PO');
    expect(blockingReason('awaiting_receipt', { po: 'ok', gr: 'partial' })).toBe('Invoiced quantity exceeds accepted receipt (rejected units)');
  });
});

describe('Invoice KPIs and chips (invKpis 4668, invChips 4666)', () => {
  const kpiOf = (list: ProtoInvoice[]) =>
    invoiceKpis(list.map((i) => ({ status: supplierInvoiceStatus.code(i.status), amountEur: i.amount, dueDate: isoOfDisplayDate(i.dueDate)! })), STATUS_DATE_ISO);

  it('seed: 5 to process (€1,724,160) · 3 blocked · 2 awaiting receipt · 0 approved · 5 due within 30 days', () => {
    const k = kpiOf(INVOICES);
    const g = G.seed.en.inv.kpis;
    expect([k.toProcess, moneyEur(k.toProcessEur, 'en'), k.blocked, k.awaitingReceipt, k.approved, k.dueWithin30]).toEqual([g[0].value, g[0].sub, g[1].value, g[2].value, g[3].value, g[4].value]);
  });

  it('after "Approve received part" on INV-HC-7781: prototype values', () => {
    const list = INVOICES.map((i) => (i.id === 'INV-HC-7781' ? { ...i, status: 'Approved for payment', amount: i.grAmt } : i));
    const k = kpiOf(list);
    const g = G.scenarios.en.afterPartial.inv.kpis;
    expect([k.toProcess, moneyEur(k.toProcessEur, 'en'), k.blocked, k.awaitingReceipt, k.approved, k.dueWithin30]).toEqual([g[0].value, g[0].sub, g[1].value, g[2].value, g[3].value, g[4].value]);
  });

  it('after rejecting INV-LE-2210 the invoice is closed (deviation: the prototype still counted it, 08 OQ5)', () => {
    const list = INVOICES.map((i) =>
      i.id === 'INV-HC-7781' ? { ...i, status: 'Approved for payment', amount: i.grAmt } : i.id === 'INV-LE-2210' ? { ...i, status: 'Rejected' } : i,
    );
    const k = kpiOf(list);
    const g = G.scenarios.en.afterReject.inv.kpis;
    expect([g[0].value, g[0].sub, g[4].value]).toEqual([5, '€1,697,360', 5]);
    expect([k.toProcess, moneyEur(k.toProcessEur, 'en'), k.blocked, k.dueWithin30]).toEqual([4, '€1,690,480', 1, 4]);
    expect(invoiceChipStatuses(list.map((i) => ({ status: supplierInvoiceStatus.code(i.status) })))).toEqual(['blocked', 'awaiting_receipt', 'no_po', 'approved_for_payment', 'paid', 'rejected']);
  });

  it('"Due within 30 days" follows the due date', () => {
    const base = { status: 'blocked' as const, amountEur: 1 };
    expect(invoiceKpis([{ ...base, dueDate: '2026-10-25' }, { ...base, dueDate: '2026-10-26' }, { ...base, dueDate: '2026-09-01' }], STATUS_DATE_ISO).dueWithin30).toBe(2);
  });

  it('chips: All + the five prototype statuses with their counts', () => {
    const statuses = invoiceChipStatuses(INVOICES.map((i) => ({ status: supplierInvoiceStatus.code(i.status) })));
    const chips = [['All', INVOICES.length], ...statuses.map((s) => [supplierInvoiceStatus.label(s), INVOICES.filter((i) => supplierInvoiceStatus.code(i.status) === s).length])];
    expect(chips).toEqual(G.seed.en.inv.chips);
  });
});

describe('RFQs (rfqRows 4650, rfqKpis 4652, rfqVals 4653)', () => {
  const asState = (r: ProtoRfq) => ({ status: rfqStatus.code(r.status), quoteCount: r.quotes.length, awardedTo: r.chosen });

  it('KPIs: 3 open RFQs · 1 ready to award · 8 quotes', () => {
    const k = rfqKpis(RFQS.map((r) => ({ status: rfqStatus.code(r.status), quoteCount: r.quotes.length })));
    const g = G.seed.en.rfq.kpis;
    expect([k.open, `${k.readyToAward} ready to award`, k.quotes]).toEqual([g[0].value, g[0].sub, g[1].value]);
    // After "Compare quotes" on RFQ-2026-033: 2 ready to award.
    const after = rfqKpis(RFQS.map((r) => ({ status: r.id === 'RFQ-2026-033' ? 'comparing' : rfqStatus.code(r.status), quoteCount: r.quotes.length })));
    expect(`${after.readyToAward} ready to award`).toBe(G.scenarios.en.afterCompare.rfq.kpis[0].sub);
  });

  it('rows: quotes text and row actions', () => {
    for (const r of RFQS) {
      const row = G.seed.en.rfq.rows.find((x) => x.id === r.id)!;
      const q = r.quotes.map(([supplier, unitPriceEur, leadWeeks]) => ({ supplier, unitPriceEur, leadWeeks }));
      expect([r.id, quotesText(q, 'en'), rfqActions(asState(r))]).toEqual([r.id, row.quotesText, { canSend: row.canSend, canCompare: row.canCompare }]);
      expect(quotesText(q, 'fr')).toBe(r.quotes.length ? `${r.quotes.length} quotes · from ${moneyEur(Math.min(...q.map((x) => x.unitPriceEur)), 'fr')}` : 'No quote yet');
    }
    expect(quotesText([{ unitPriceEur: 900 }], 'en')).toBe('1 quote · from €900');
  });

  it('quote comparison: best price, shortest lead time, delta × quantity, award rights and hint per role', () => {
    for (const r of RFQS) {
      const cmp = compareQuotes(r.quotes.map(([supplier, unitPriceEur, leadWeeks]) => ({ supplier, unitPriceEur, leadWeeks })), r.qty);
      for (const role of ['director', 'pm', 'procurement', 'quality'] as const) {
        const g = G.rfqDrawers.en[r.id][role];
        expect(cmp.map((c) => [c.supplier, c.isBest, c.isFastest, moneyEur(c.totalEur!, 'en'), c.deltaEur ? '+' + moneyEur(c.deltaEur, 'en') : '—'])).toEqual(
          g.quotes.map((q) => [q.sup, q.priceColor === 'var(--color-accent-300)', q.leadColor === 'var(--color-accent-300)', q.total, q.delta]),
        );
        expect(g.quotes.map((q) => q.canAward)).toEqual(r.quotes.map(() => canAwardRfq(asState(r), role)));
        expect(rfqHint({ ...asState(r), purchaseOrderNumber: null, awardedInKeystone: false }, role)).toBe(g.hint);
      }
    }
  });

  it('an award made in Keystone without an order says so', () => {
    const r = { status: 'awarded' as const, quoteCount: 2, awardedTo: 'ABB' };
    expect(rfqHint({ ...r, purchaseOrderNumber: 'PO-1100', awardedInKeystone: true }, 'pm')).toBe('Awarded to ABB — purchase order created as draft.');
    expect(rfqHint({ ...r, purchaseOrderNumber: null, awardedInKeystone: true }, 'pm')).toBe('Awarded to ABB — no purchase order drafted (no project or quantity on the RFQ).');
  });
});

describe('Supplier scorecard (supRows 4674, supKpis 4675)', () => {
  it('KPIs: 8 active · 4 rated A · 90% on time · 97% quality · 1 rated C', () => {
    const k = supplierKpis(SUPPLIERS.map(([, otd, q, ncr, grade]) => ({ onTimeDeliveryPct: otd, qualityAcceptancePct: q, ncrRatePct: ncr, grade })));
    const g = G.seed.en.sup.kpis;
    expect([k.active, `${k.ratedA} rated A`, `${k.onTimePct}%`, `${k.qualityPct}%`, k.ratedC]).toEqual([g[0].value, g[0].sub, g[1].value, g[2].value, g[3].value]);
  });

  it('attention colours: on-time below 85 %, NCR rate above 2 %', () => {
    const flags = SUPPLIERS.map(([name, otd, , ncr]) => [name, supplierAttention({ onTimeDeliveryPct: otd, ncrRatePct: ncr })]);
    expect(flags.filter(([, f]) => (f as { onTime: boolean }).onTime).map(([n]) => n)).toEqual(['Cotswold Fire Systems', 'Solaris PV']);
    expect(flags.filter(([, f]) => (f as { ncrRate: boolean }).ncrRate).map(([n]) => n)).toEqual(['Halvorsen Cranes', 'Brightline Electrics']);
  });
});

describe('My approvals items (apprItems 4728–4729)', () => {
  const rfqInbox = RFQS.map((r) => ({
    number: r.id, title: r.title, status: rfqStatus.code(r.status), awardedTo: r.chosen, quoteCount: r.quotes.length,
    awardRuleLabel: awardRule.label(awardRule.code(r.rule)), replyDueOn: isoOfDisplayDate(r.due)!, owner: r.owner,
  }));
  const invInbox = INVOICES.map((i) => ({
    number: i.id, supplier: i.supplier, status: supplierInvoiceStatus.code(i.status), amountEur: i.amount, match: match3(asMatch(i)), invoiceDate: isoOfDisplayDate(i.date)!,
  }));

  it('EN: same items as the prototype for procurement (RFQ award + 3 invoices)', () => {
    const t = makeT('en');
    const items = [...rfqAwardItems(rfqInbox, t), ...invoiceApprovalItems(invInbox, 'en')];
    expect(items.map((i) => ({ id: i.id, title: i.title, sub: i.sub, when: i.when, who: i.who }))).toEqual(
      G.myapprovals.en.procurement.map((i) => ({ id: i.id, title: i.title, sub: i.sub, when: i.when.replace(/^0/, ''), who: i.who })),
    );
    expect(items.map((i) => i.href)).toEqual([
      '/purchasing/sourcing?rfq=RFQ-2026-031', '/purchasing/sourcing?tab=inv&inv=INV-HC-7781', '/purchasing/sourcing?tab=inv&inv=INV-BX-55120', '/purchasing/sourcing?tab=inv&inv=INV-LE-2210',
    ]);
    expect(items.every((i) => i.decision === null)).toBe(true);
    expect(items.map((i) => i.whenIso)).toEqual(['2026-09-30', '2026-09-10', '2026-09-24', '2026-09-25']);
  });

  it('FR: the inbox translation of the items gives the prototype text, the award rule translated too', () => {
    const t = makeT('fr');
    const items = [...rfqAwardItems(rfqInbox, t), ...invoiceApprovalItems(invInbox, 'fr')];
    const shown = items.map((i) => ({ title: t(i.title), sub: t(i.sub), when: t(i.when), who: t(i.who) }));
    const proto = G.myapprovals.fr.procurement.map((i) => ({ title: i.title, sub: i.sub, when: i.when, who: i.who }));
    expect(shown.slice(1)).toEqual(proto.slice(1));
    expect(proto[0].sub).toBe('3 devis · Lowest total cost of ownership');
    expect(shown[0]).toEqual({ ...proto[0], sub: '3 devis · Coût total de possession le plus bas' });
  });

  it('a Blocked invoice whose order amount differs says so', () => {
    expect(invoiceApprovalItems([{ number: 'X', supplier: 'S', status: 'blocked', amountEur: 10, match: { po: 'diff', gr: 'ok' }, invoiceDate: '2026-09-01' }], 'en')[0].sub).toBe('Amount differs from PO');
  });
});

describe('URLs and the New RFQ form', () => {
  it('sourcingHref keeps the default tab out of the URL', () => {
    expect(sourcingHref()).toBe('/purchasing/sourcing');
    expect(sourcingHref({ tab: 'inv', status: 'blocked', inv: 'INV-HC-7781' })).toBe('/purchasing/sourcing?tab=inv&status=blocked&inv=INV-HC-7781');
    expect(sourcingHref({ tab: 'sup' })).toBe('/purchasing/sourcing?tab=sup');
  });

  it('parseNewRfq: required fields, reply date (EN / FR / default), incoterm code', () => {
    const ok = { title: ' Steel plate S355 ', suppliers: 'ArcelorMittal, Dillinger;Salzgitter, Dillinger', articles: 'KS-PLT-S355 × 192', due: '15 Oct 2026', incoterm: 'DAP' };
    expect(parseNewRfq(ok, STATUS_DATE_ISO)).toEqual({
      ok: true,
      value: { title: 'Steel plate S355', suppliers: ['ArcelorMittal', 'Dillinger', 'Salzgitter'], articles: 'KS-PLT-S355 × 192', replyDueOn: '2026-10-15', incoterm: 'DAP' },
    });
    expect(parseNewRfq({ ...ok, due: '20 oct. 2026' }, STATUS_DATE_ISO)).toMatchObject({ ok: true, value: { replyDueOn: '2026-10-20' } });
    expect(parseNewRfq({ ...ok, due: '' }, STATUS_DATE_ISO)).toMatchObject({ ok: true, value: { replyDueOn: '2026-10-15' } });
    expect(parseNewRfq({ ...ok, incoterm: '' }, STATUS_DATE_ISO)).toMatchObject({ ok: true, value: { incoterm: 'DAP' } });
    expect(parseNewRfq({ ...ok, title: '  ' }, STATUS_DATE_ISO)).toEqual({ ok: false, error: 'The title is required' });
    expect(parseNewRfq({ ...ok, suppliers: ' , ;' }, STATUS_DATE_ISO)).toEqual({ ok: false, error: 'Name at least one supplier' });
    expect(parseNewRfq({ ...ok, articles: '' }, STATUS_DATE_ISO)).toEqual({ ok: false, error: 'The articles are required' });
    expect(parseNewRfq({ ...ok, due: 'next week' }, STATUS_DATE_ISO)).toEqual({ ok: false, error: 'Enter the reply date as a date (e.g. 15 Oct 2026)' });
    expect(parseNewRfq({ ...ok, due: '1 Sep 2026' }, STATUS_DATE_ISO)).toEqual({ ok: false, error: 'The reply date is before the status date' });
    expect(parseNewRfq({ ...ok, incoterm: 'CIF' }, STATUS_DATE_ISO)).toEqual({ ok: false, error: 'Unknown incoterm' });
    expect(parseNewRfq({ ...ok, title: 42 }, STATUS_DATE_ISO)).toEqual({ ok: false, error: 'The title is required' });
  });
});
